import resvgWasm from "../node_modules/@resvg/resvg-wasm/index_bg.wasm";
import webpEncWasm from "../node_modules/@jsquash/webp/codec/enc/webp_enc_simd.wasm";
import webpDecWasm from "../node_modules/@jsquash/webp/codec/dec/webp_dec.wasm";
import pngWasm from "../node_modules/@jsquash/png/codec/pkg/squoosh_png_bg.wasm";
import jpegDecWasm from "../node_modules/@jsquash/jpeg/codec/dec/mozjpeg_dec.wasm";
import dejavu from "../fonts/DejaVuSans.ttf";
import { Resvg, initWasm } from "@resvg/resvg-wasm";
import { init as initWebpEnc, default as encodeWebp } from "@jsquash/webp/encode";
import { init as initWebpDec, default as decodeWebp } from "@jsquash/webp/decode";
import { init as initPng, default as decodePng } from "@jsquash/png/decode";
import { init as initJpeg, default as decodeJpeg } from "@jsquash/jpeg/decode";
import { GifReader } from "omggif";

export const SVG_WIDTH = 768;
export const MIN_DIM = 200;

let ready: Promise<void> | undefined;
const setup = () =>
  (ready ??= (async () => {
    await initWasm(resvgWasm as WebAssembly.Module);
    await initWebpEnc(webpEncWasm as WebAssembly.Module);
    await initWebpDec(webpDecWasm as WebAssembly.Module);
    await initPng(pngWasm as WebAssembly.Module);
    await initJpeg(jpegDecWasm as WebAssembly.Module);
  })());

const isSvg = (b: Uint8Array) => new TextDecoder().decode(b.subarray(0, 500)).toLowerCase().includes("<svg");

const sniff = (b: Uint8Array) => {
  if (b[0] === 0x89 && b[1] === 0x50) return "png";
  if (b[0] === 0xff && b[1] === 0xd8) return "jpeg";
  if (b[0] === 0x47 && b[1] === 0x49) return "gif";
  if (b[0] === 0x52 && b[1] === 0x49 && b[8] === 0x57) return "webp";
  return "unknown";
};

export type Result = { webp: Uint8Array; kind: string; width: number; height: number };

export const processWasm = async (raw: Uint8Array, opts: { fonts: boolean }): Promise<Result> => {
  await setup();
  let img: ImageData;
  let kind: string;

  if (isSvg(raw)) {
    kind = "svg";
    const resvg = new Resvg(raw, {
      fitTo: { mode: "width", value: SVG_WIDTH },
      font: opts.fonts
        ? { fontBuffers: [new Uint8Array(dejavu as ArrayBuffer)], defaultFontFamily: "DejaVu Sans", loadSystemFonts: false }
        : { loadSystemFonts: false },
    });
    const r = resvg.render();
    img = new ImageData(new Uint8ClampedArray(r.pixels), r.width, r.height);
    r.free();
    resvg.free();
  } else {
    kind = sniff(raw);
    const ab = raw.buffer.slice(raw.byteOffset, raw.byteOffset + raw.byteLength) as ArrayBuffer;
    if (kind === "png") img = await decodePng(ab);
    else if (kind === "jpeg") img = await decodeJpeg(ab);
    else if (kind === "webp") img = await decodeWebp(ab);
    else if (kind === "gif") {
      const g = new GifReader(raw as unknown as Buffer);
      const px = new Uint8ClampedArray(g.width * g.height * 4);
      g.decodeAndBlitFrameRGBA(0, px);
      img = new ImageData(px, g.width, g.height);
    } else throw new Error("undecodable");
    if (Math.min(img.width, img.height) < MIN_DIM) throw new Error(`too small (${img.width}x${img.height})`);
  }

  const out = await encodeWebp(img, { quality: 80 });
  return { webp: new Uint8Array(out), kind, width: img.width, height: img.height };
};

export const wasmSizes = () => ({
  resvg: (resvgWasm as unknown as WebAssembly.Module) && 0,
});
