import { WorkflowEntrypoint, WorkflowEvent, WorkflowStep } from "cloudflare:workers";
import { processWasm } from "./wasm";
import { processBinding } from "./images-binding";

interface Env {
  IMAGES: ImagesBinding;
  WF: Workflow;
}

const headersFor = (extra: Record<string, string | number>) => {
  const h = new Headers({ "content-type": "image/webp" });
  for (const [k, v] of Object.entries(extra)) h.set(`x-${k}`, String(v));
  return h;
};

export default {
  async fetch(req: Request, env: Env): Promise<Response> {
    const url = new URL(req.url);

    if (url.pathname === "/process") {
      const variant = url.searchParams.get("v") ?? "wasm";
      const n = Number(url.searchParams.get("n") ?? 1);
      const raw = new Uint8Array(await req.arrayBuffer());
      try {
        if (variant === "binding") {
          const r = await processBinding(env.IMAGES, raw);
          return new Response(r.webp, { headers: headersFor({ info: JSON.stringify(r.info), size: r.webp.length }) });
        }
        const fonts = url.searchParams.get("fonts") === "1";
        let r = await processWasm(raw, { fonts });
        for (let i = 1; i < n; i++) r = await processWasm(raw, { fonts });
        return new Response(r.webp, { headers: headersFor({ kind: r.kind, w: r.width, h: r.height, size: r.webp.length }) });
      } catch (e) {
        return new Response(String((e as Error)?.stack ?? e), { status: 422 });
      }
    }

    if (url.pathname === "/workflow" && req.method === "POST") {
      const inst = await env.WF.create({ params: { urls: await req.json() } });
      return Response.json({ id: inst.id });
    }
    if (url.pathname.startsWith("/workflow/")) {
      const inst = await env.WF.get(url.pathname.split("/")[2]);
      return Response.json(await inst.status());
    }
    return new Response("nagara-spike-images");
  },
};

export class ImageWorkflow extends WorkflowEntrypoint<Env, { urls: string[] }> {
  async run(event: WorkflowEvent<{ urls: string[] }>, step: WorkflowStep) {
    const results = await step.do("images", async () => {
      const out: unknown[] = [];
      for (const u of event.payload.urls) {
        const res = await fetch(u, { headers: { "user-agent": "Mozilla/5.0 (compatible; nagara-spike)" } });
        const raw = new Uint8Array(await res.arrayBuffer());
        try {
          const r = await processWasm(raw, { fonts: true });
          out.push({ u, kind: r.kind, w: r.width, h: r.height, webp: r.webp.length });
        } catch (e) {
          out.push({ u, error: String(e) });
        }
      }
      return out;
    });
    return results;
  }
}
